-- ============================================================
-- Update Demo Scheduled email template to include
-- auto-created Google Meet details ({{demo.*}} merge tags)
-- ============================================================

UPDATE sales_pipeline_email_templates SET
  subject    = 'Your Aliice demo is confirmed, {{contact.first_name}} 🗓️',
  body_html  = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Demo Confirmed</title></head><body style="margin:0;padding:0;background:#f1f5f9;font-family:''Segoe UI'',Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:32px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);"><tr><td style="background:#10b981;height:5px;font-size:0;line-height:0;">&nbsp;</td></tr><tr><td style="background:#ffffff;padding:36px 40px 24px;text-align:center;"><img src="https://www.aliice.app/logos/aliice-logo.png" alt="Aliice" width="110" style="display:block;margin:0 auto 20px;"/><h1 style="margin:0;color:#10b981;font-size:26px;font-weight:700;">Your demo is confirmed! 🗓️</h1><p style="margin:10px 0 0;color:#64748b;font-size:15px;">We can''t wait to show you Aliice, {{contact.first_name}}</p></td></tr><tr><td style="padding:8px 40px 40px;"><p style="margin:0 0 24px;color:#334155;font-size:16px;line-height:1.7;">Hi <strong>{{contact.first_name}}</strong>, your demo for <strong>{{org.name}}</strong> has been scheduled. Here are your meeting details:</p><table width="100%" cellpadding="0" cellspacing="0" style="background:#f0fdf4;border-radius:12px;padding:24px;margin:0 0 20px;"><tr><td><p style="margin:0 0 6px;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;color:#059669;">📅 Date &amp; Time</p><p style="margin:0 0 16px;font-size:18px;font-weight:700;color:#0f172a;">{{demo.date}}</p><p style="margin:0 0 6px;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;color:#059669;">🕐 Time</p><p style="margin:0 0 16px;font-size:18px;font-weight:700;color:#0f172a;">{{demo.time}}</p><p style="margin:0 0 6px;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;color:#059669;">🎥 Google Meet Link</p><a href="{{demo.meet_link}}" style="display:inline-block;margin:0 0 4px;font-size:15px;font-weight:600;color:#10b981;word-break:break-all;">{{demo.meet_link}}</a></td></tr></table><table width="100%" cellpadding="0" cellspacing="0" style="background:#f0fdf4;border-radius:12px;padding:24px;margin:0 0 20px;"><tr><td><p style="margin:0 0 16px;font-size:15px;font-weight:700;color:#065f46;">What we''ll cover in 30 minutes</p><p style="margin:0 0 10px;font-size:14px;color:#334155;border-bottom:1px solid #bbf7d0;padding-bottom:10px;"><span style="display:inline-block;width:22px;height:22px;background:#10b981;border-radius:50%;color:#fff;font-size:11px;font-weight:700;text-align:center;line-height:22px;margin-right:8px;">1</span><strong>Platform overview</strong> — the full Aliice suite in action</p><p style="margin:0 0 10px;font-size:14px;color:#334155;border-bottom:1px solid #bbf7d0;padding-bottom:10px;"><span style="display:inline-block;width:22px;height:22px;background:#10b981;border-radius:50%;color:#fff;font-size:11px;font-weight:700;text-align:center;line-height:22px;margin-right:8px;">2</span><strong>Your use-case</strong> — tailored walkthrough for {{org.name}}</p><p style="margin:0 0 10px;font-size:14px;color:#334155;border-bottom:1px solid #bbf7d0;padding-bottom:10px;"><span style="display:inline-block;width:22px;height:22px;background:#10b981;border-radius:50%;color:#fff;font-size:11px;font-weight:700;text-align:center;line-height:22px;margin-right:8px;">3</span><strong>Pricing &amp; next steps</strong> — transparent, no surprises</p><p style="margin:0;font-size:14px;color:#334155;"><span style="display:inline-block;width:22px;height:22px;background:#10b981;border-radius:50%;color:#fff;font-size:11px;font-weight:700;text-align:center;line-height:22px;margin-right:8px;">4</span><strong>Q&amp;A</strong> — ask us anything</p></td></tr></table><table width="100%" cellpadding="0" cellspacing="0" style="background:#fffbeb;border-left:4px solid #f59e0b;border-radius:0 8px 8px 0;padding:16px 20px;margin:0 0 28px;"><tr><td><p style="margin:0;font-size:14px;font-weight:700;color:#92400e;">💡 To get the most out of your demo</p><p style="margin:8px 0 0;font-size:13px;color:#78350f;line-height:1.6;">Think about your biggest clinic pain-points — we''ll show you exactly how Aliice solves them.</p></td></tr></table><table cellpadding="0" cellspacing="0" style="margin:0 auto 16px;"><tr><td style="background:#10b981;border-radius:10px;"><a href="{{demo.meet_link}}" style="display:block;padding:14px 36px;color:#ffffff;font-size:15px;font-weight:700;text-decoration:none;">Join Google Meet →</a></td></tr></table><table cellpadding="0" cellspacing="0" style="margin:0 auto;"><tr><td style="border:1px solid #d1fae5;border-radius:10px;"><a href="{{demo.calendar_link}}" style="display:block;padding:12px 28px;color:#10b981;font-size:14px;font-weight:600;text-decoration:none;">View in Google Calendar →</a></td></tr></table></td></tr><tr><td style="background:#f8fafc;padding:24px 40px;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;font-size:12px;color:#94a3b8;">Need to reschedule? Reply to this email — we''re happy to help.</p><p style="margin:6px 0 0;font-size:12px;color:#94a3b8;"><a href="mailto:hello@aliice.app" style="color:#10b981;text-decoration:none;">hello@aliice.app</a></p><p style="margin:8px 0 0;font-size:11px;color:#cbd5e1;">© 2025 Aliice · All-in-one clinic management platform</p></td></tr></table></td></tr></table></body></html>',

  subject_fr = 'Votre démo Aliice est confirmée, {{contact.first_name}} 🗓️',

  body_html_fr = '<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Démo confirmée</title></head><body style="margin:0;padding:0;background:#f1f5f9;font-family:''Segoe UI'',Arial,sans-serif;"><table width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:32px 0;"><tr><td align="center"><table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);"><tr><td style="background:#10b981;height:5px;font-size:0;line-height:0;">&nbsp;</td></tr><tr><td style="background:#ffffff;padding:36px 40px 24px;text-align:center;"><img src="https://www.aliice.app/logos/aliice-logo.png" alt="Aliice" width="110" style="display:block;margin:0 auto 20px;"/><h1 style="margin:0;color:#10b981;font-size:26px;font-weight:700;">Votre démo est confirmée ! 🗓️</h1><p style="margin:10px 0 0;color:#64748b;font-size:15px;">Nous avons hâte de vous montrer Aliice, {{contact.first_name}}</p></td></tr><tr><td style="padding:8px 40px 40px;"><p style="margin:0 0 24px;color:#334155;font-size:16px;line-height:1.7;">Bonjour <strong>{{contact.first_name}}</strong>, votre démo pour <strong>{{org.name}}</strong> est planifiée. Voici les détails de votre réunion :</p><table width="100%" cellpadding="0" cellspacing="0" style="background:#f0fdf4;border-radius:12px;padding:24px;margin:0 0 20px;"><tr><td><p style="margin:0 0 6px;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;color:#059669;">📅 Date</p><p style="margin:0 0 16px;font-size:18px;font-weight:700;color:#0f172a;">{{demo.date}}</p><p style="margin:0 0 6px;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;color:#059669;">🕐 Heure</p><p style="margin:0 0 16px;font-size:18px;font-weight:700;color:#0f172a;">{{demo.time}}</p><p style="margin:0 0 6px;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;color:#059669;">🎥 Lien Google Meet</p><a href="{{demo.meet_link}}" style="display:inline-block;margin:0 0 4px;font-size:15px;font-weight:600;color:#10b981;word-break:break-all;">{{demo.meet_link}}</a></td></tr></table><table width="100%" cellpadding="0" cellspacing="0" style="background:#f0fdf4;border-radius:12px;padding:24px;margin:0 0 20px;"><tr><td><p style="margin:0 0 16px;font-size:15px;font-weight:700;color:#065f46;">Ce que nous allons couvrir en 30 minutes</p><p style="margin:0 0 10px;font-size:14px;color:#334155;border-bottom:1px solid #bbf7d0;padding-bottom:10px;"><span style="display:inline-block;width:22px;height:22px;background:#10b981;border-radius:50%;color:#fff;font-size:11px;font-weight:700;text-align:center;line-height:22px;margin-right:8px;">1</span><strong>Vue d''ensemble</strong> — toute la suite Aliice en action</p><p style="margin:0 0 10px;font-size:14px;color:#334155;border-bottom:1px solid #bbf7d0;padding-bottom:10px;"><span style="display:inline-block;width:22px;height:22px;background:#10b981;border-radius:50%;color:#fff;font-size:11px;font-weight:700;text-align:center;line-height:22px;margin-right:8px;">2</span><strong>Votre cas d''usage</strong> — parcours personnalisé pour {{org.name}}</p><p style="margin:0 0 10px;font-size:14px;color:#334155;border-bottom:1px solid #bbf7d0;padding-bottom:10px;"><span style="display:inline-block;width:22px;height:22px;background:#10b981;border-radius:50%;color:#fff;font-size:11px;font-weight:700;text-align:center;line-height:22px;margin-right:8px;">3</span><strong>Tarifs &amp; prochaines étapes</strong> — transparence totale</p><p style="margin:0;font-size:14px;color:#334155;"><span style="display:inline-block;width:22px;height:22px;background:#10b981;border-radius:50%;color:#fff;font-size:11px;font-weight:700;text-align:center;line-height:22px;margin-right:8px;">4</span><strong>Questions / Réponses</strong> — posez-nous tout</p></td></tr></table><table width="100%" cellpadding="0" cellspacing="0" style="background:#fffbeb;border-left:4px solid #f59e0b;border-radius:0 8px 8px 0;padding:16px 20px;margin:0 0 28px;"><tr><td><p style="margin:0;font-size:14px;font-weight:700;color:#92400e;">💡 Pour profiter au maximum de votre démo</p><p style="margin:8px 0 0;font-size:13px;color:#78350f;line-height:1.6;">Pensez à vos principaux défis cliniques — nous vous montrerons exactement comment Aliice les résout.</p></td></tr></table><table cellpadding="0" cellspacing="0" style="margin:0 auto 16px;"><tr><td style="background:#10b981;border-radius:10px;"><a href="{{demo.meet_link}}" style="display:block;padding:14px 36px;color:#ffffff;font-size:15px;font-weight:700;text-decoration:none;">Rejoindre Google Meet →</a></td></tr></table><table cellpadding="0" cellspacing="0" style="margin:0 auto;"><tr><td style="border:1px solid #d1fae5;border-radius:10px;"><a href="{{demo.calendar_link}}" style="display:block;padding:12px 28px;color:#10b981;font-size:14px;font-weight:600;text-decoration:none;">Voir dans Google Agenda →</a></td></tr></table></td></tr><tr><td style="background:#f8fafc;padding:24px 40px;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;font-size:12px;color:#94a3b8;">Besoin de reporter ? Répondez à cet e-mail — nous serons ravis de vous aider.</p><p style="margin:6px 0 0;font-size:12px;color:#94a3b8;"><a href="mailto:hello@aliice.app" style="color:#10b981;text-decoration:none;">hello@aliice.app</a></p><p style="margin:8px 0 0;font-size:11px;color:#cbd5e1;">© 2025 Aliice · Plateforme tout-en-un pour cliniques</p></td></tr></table></td></tr></table></body></html>'

WHERE name = 'Demo Confirmation – Your Aliice Demo is Confirmed';
